"""TOEIC Part 5 bank batch 2: original office, travel, and purchasing items."""
from lib import P5


P5("The procurement officer requested three ___ from different suppliers.", ["quotations", "quote", "quoting", "quoted"], "pos",
   "Three bổ nghĩa cho danh từ đếm được số nhiều quotations, tức là các báo giá.", "commerce", 3,
   expl_en="Three requires a plural countable noun. Quotations are written offers stating a price.")
P5("The receptionist will notify visitors when their host ___.", ["arrives", "arrive", "arrived", "will arrive"], "agreement",
   "Chủ ngữ their host số ít nên động từ hiện tại đơn là arrives; mệnh đề when không dùng will.", "office", 2,
   expl_en="Host is singular, so the present simple form is arrives. A future time clause uses present simple rather than will.")
P5("The company reduced shipping costs by negotiating a more favorable ___.", ["contract", "contractual", "contracting", "contracted"], "pos",
   "Sau a more favorable cần danh từ contract; negotiating a contract có nghĩa là thương lượng hợp đồng.", "logistics", 3,
   expl_en="The article a and adjective favorable require a singular noun. Contract names the agreement being negotiated.")
P5("Please ensure that the package is labeled ___.", ["correctly", "correct", "correction", "correctness"], "pos",
   "Trạng từ correctly bổ nghĩa cho cách gói hàng được dán nhãn.", "logistics", 2,
   expl_en="The adverb correctly modifies is labeled and describes how the package should be labeled.")
P5("The new policy applies to all employees, ___ their job title.", ["regardless of", "because", "until", "so that"], "preposition",
   "Regardless of đi trước danh từ their job title và nghĩa là bất kể chức danh.", "hr", 4,
   expl_en="Regardless of is followed by a noun phrase and means that the policy applies without considering job title.")
P5("The flight was delayed ___ heavy fog at the airport.", ["because of", "although", "unless", "whereas"], "preposition",
   "Because of đi trước cụm danh từ heavy fog để nêu nguyên nhân.", "travel", 2,
   expl_en="Because of introduces a noun phrase that gives the reason for the delay.")
P5("The design team is expected ___ the first draft by Monday.", ["to finish", "finishing", "finish", "finished"], "infinitive",
   "Cấu trúc be expected to + động từ nguyên mẫu; chọn to finish.", "marketing", 3,
   expl_en="The passive expression be expected is followed by an infinitive: to finish the draft.")
P5("The director asked whether the figures were ___ enough to publish.", ["reliable", "reliably", "reliability", "rely"], "pos",
   "Sau were cần tính từ reliable để mô tả figures.", "finance", 3,
   expl_en="The linking verb were requires an adjective. Reliable describes figures that can be trusted.")
P5("The café will close early today ___ a private event.", ["for", "since", "while", "despite"], "preposition",
   "For + cụm danh từ có thể nêu lý do trong thông báo; private event là lý do đóng cửa.", "hospitality", 3,
   expl_en="For introduces the reason for closing early. It is followed by the noun phrase a private event.")
P5("The software update includes several security ___ for mobile users.", ["improvements", "improve", "improved", "improving"], "pos",
   "Several security cần danh từ số nhiều improvements.", "tech", 2,
   expl_en="Several requires a plural noun. Improvements names the security changes included in the update.")
P5("The courier delivered the documents ___ than the client had expected.", ["earlier", "early", "earliest", "earliness"], "comparison",
   "Than báo hiệu so sánh hơn; earlier nghĩa là sớm hơn.", "logistics", 2,
   expl_en="Than requires the comparative adverb earlier. The delivery happened before the client's expectation.")
P5("The committee will meet to discuss ___ the proposal should be revised.", ["whether", "during", "despite", "because of"], "conjunction",
   "Whether mở đầu mệnh đề gián tiếp có hai khả năng có nên sửa đề xuất hay không.", "office", 4,
   expl_en="Whether introduces an indirect yes-or-no question after discuss. The committee will consider if revision is needed.")
P5("Our representatives are available to answer questions ___ the product demonstration.", ["after", "among", "unless", "because"], "preposition",
   "After đi trước cụm danh từ the product demonstration và chỉ thời điểm sau buổi trình diễn.", "sales", 2,
   expl_en="After is followed by the noun phrase the product demonstration and identifies when representatives are available.")
P5("The office manager reminded staff ___ the new visitor procedure.", ["of", "for", "at", "with"], "preposition",
   "Remind someone of something là cụm cố định; staff được nhắc về quy trình.", "office", 3,
   expl_en="Remind someone of something is the fixed construction. The staff were reminded of the procedure.")
P5("The hotel requires guests to provide a credit card ___ check-in.", ["at", "on", "in", "to"], "preposition",
   "Cụm at check-in chỉ thời điểm làm thủ tục nhận phòng.", "hospitality", 2,
   expl_en="At is used with a specific event or point in time: at check-in.")
P5("The report was praised for its ___ analysis of customer behavior.", ["thorough", "thoroughly", "thoroughness", "through"], "pos",
   "Tính từ thorough đứng trước danh từ analysis để mô tả phân tích kỹ lưỡng.", "marketing", 3,
   expl_en="An adjective is required before analysis. Thorough means complete and careful.")
P5("The sales figures have increased steadily ___ the new campaign began.", ["since", "during", "until", "by"], "conjunction",
   "Since nối với mệnh đề the new campaign began và chỉ mốc bắt đầu.", "sales", 3,
   expl_en="Since introduces the starting point of a continuing change: the campaign began.")
P5("The company hired a consultant to improve its online ___.", ["presence", "present", "presently", "presentation"], "pos",
   "Online presence là cụm danh từ chỉ sự hiện diện trực tuyến.", "marketing", 3,
   expl_en="Online presence is the standard noun phrase for how visible an organization is online.")
P5("The technician found the instructions too ___ to follow.", ["confusing", "confused", "confusion", "confuse"], "pos",
   "Instructions gây ra cảm giác khó hiểu nên dùng confusing, không dùng confused cho người.", "tech", 3,
   expl_en="Confusing describes something that causes confusion. The instructions cause the difficulty, so confusing is correct.")
P5("The museum's opening hours may change ___ public holidays.", ["on", "at", "in", "to"], "preposition",
   "Dùng on với các ngày hoặc dịp cụ thể như public holidays.", "travel", 2,
   expl_en="On is used with days and named occasions. Public holidays are the occasions when the hours may change.")
P5("Please keep the doors closed so that the air-conditioning system can operate ___.", ["efficiently", "efficient", "efficiency", "efficiencies"], "pos",
   "Operate là động từ nên cần trạng từ efficiently để mô tả cách hoạt động.", "facilities", 3,
   expl_en="An adverb modifies operate. Efficiently explains how the air-conditioning system can operate.")
P5("The supplier will replace any items that arrive ___.", ["damaged", "damage", "damaging", "damages"], "pos",
   "Sau arrive cần phân từ damaged để mô tả tình trạng của items.", "logistics", 3,
   expl_en="Damaged is a past participle adjective describing items that arrive in a damaged condition.")
P5("The manager approved the request, ___ it exceeded the original budget.", ["even though", "because of", "during", "so that"], "conjunction",
   "Even though nối hai mệnh đề tương phản: vẫn duyệt dù vượt ngân sách.", "finance", 4,
   expl_en="Even though introduces a complete contrasting clause. The request was approved despite exceeding the budget.")
P5("The conference room is reserved ___ the afternoon session.", ["for", "to", "at", "by"], "preposition",
   "Reserve something for an event là cụm dùng for để chỉ mục đích sử dụng.", "events", 2,
   expl_en="The room is reserved for the session, so for introduces the intended use.")
P5("The brochure gives a ___ description of the tour itinerary.", ["brief", "briefly", "briefness", "briefing"], "pos",
   "Tính từ brief đứng trước danh từ description.", "travel", 2,
   expl_en="A noun is modified by an adjective. Brief describes the short description in the brochure.")
P5("The manager will review the schedule and make ___ changes if necessary.", ["any", "some of", "much", "a little"], "determiner",
   "Any đứng trước danh từ số nhiều changes trong câu điều kiện để chỉ bất kỳ thay đổi nào.", "office", 3,
   expl_en="Any is used before the plural count noun changes in this conditional sentence.")
P5("The restaurant has expanded its menu to include more vegetarian ___.", ["options", "optional", "optionally", "option"], "pos",
   "More cần danh từ số nhiều options; vegetarian options là các lựa chọn món chay.", "food_drink", 2,
   expl_en="More modifies a plural count noun here. Vegetarian options are choices for customers who do not eat meat.")
P5("The employee handbook should be read carefully before it is ___ to new staff.", ["distributed", "distribute", "distribution", "distributing"], "passive",
   "Sau it is cần phân từ để tạo bị động: is distributed.", "hr", 3,
   expl_en="The handbook receives the action, so the passive form is distributed after is.")
P5("The airline apologized ___ the cancellation and offered a refund.", ["for", "to", "with", "at"], "preposition",
   "Apologize for là cụm cố định dùng trước sự việc gây bất tiện.", "travel", 2,
   expl_en="Apologize for is the fixed phrase used before the problem being apologized for.")
P5("The new filing system makes documents much easier ___.", ["to locate", "locating", "locate", "located"], "infinitive",
   "Cấu trúc make + tân ngữ + adjective + to-infinitive: easier to locate.", "office", 3,
   expl_en="The pattern is make something easier to do. To locate completes the adjective phrase easier to locate.")
P5("The manager asked for a more ___ explanation of the price increase.", ["specific", "specify", "specifically", "specification"], "pos",
   "More cần tính từ specific đứng trước danh từ explanation.", "finance", 3,
   expl_en="More modifies the adjective specific, which describes the requested explanation.")
P5("The shipment cannot be released until the customs forms ___.", ["are completed", "complete", "completed", "will complete"], "passive",
   "Customs forms nhận hành động hoàn tất nên dùng bị động are completed; sau until không dùng will.", "logistics", 4,
   expl_en="The forms receive the action, so are completed is passive. A time clause after until uses present simple.")
